/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, DestroyRef, effect, inject, input, linkedSignal, output, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { combineLatest, of, switchMap, take } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { AppStateService } from '@shared/context/state/app-state.service';
import { matchColumns } from './column-match';
import { IMPORT_ACCEPT, readWorkbook } from './excel-reader';
import { downloadTemplate } from './excel-writer';
import { EntityImportService } from './entity-import.service';
import { ImportColumn, ImportDefinition, ImportPlan, ImportPlanColumn, ImportSheet } from './entity-import.model';

/** Campos que nunca llegan en el Excel: los asigna el sistema. */
const SYSTEM_FIELDS = ['uid', 'version'];
/** Valores de ejemplo que se muestran de cada cabecera. */
const SAMPLES = 3;
/** Cada cuánto se comprueba si sigue viva una importación que ejecuta otra pestaña. */
const REFRESH_MS = 10_000;

/** Columna esperada, con su etiqueta traducida y si es clave u obligatoria. */
interface ExpectedColumn extends ImportColumn {
  text: string;
  key: boolean;
}

/**
 * Importación de elementos desde un Excel: lee el fichero, propone qué cabecera corresponde a cada campo
 * (por parecido con su etiqueta) y crea o actualiza cada fila buscándola por la clave natural.
 *
 * Solo se ofrecen los campos que el ACL genérico deja escribir, sin `uid` ni `version` y sin los que fija el
 * contexto global (p. ej. el tenant elegido en la barra superior), que se aplican a todas las filas.
 *
 * La importación sigue en segundo plano al cerrar la pantalla; al volver se muestra su estado.
 */
@Component({
  selector: 'entity-import',
  standalone: true,
  imports: [
    CommonModule,
    MatButtonModule,
    MatFormFieldModule,
    MatIconModule,
    MatProgressBarModule,
    MatSelectModule,
    TranslocoModule,
  ],
  templateUrl: './entity-import.component.html',
  styleUrl: './entity-import.component.scss',
})
export class EntityImportComponent {
  readonly definition = input.required<ImportDefinition<any>>();
  readonly closed = output<void>();

  readonly accept = IMPORT_ACCEPT;

  private readonly imports = inject(EntityImportService);
  private readonly transloco = inject(TranslocoService);
  private readonly appState = inject(AppStateService);

  private readonly storageKey = computed(() => this.definition().storageKey);
  readonly job = computed(() => this.imports.job(this.storageKey())());
  readonly runningHere = computed(() => this.imports.isRunningHere(this.storageKey()));
  readonly runningElsewhere = computed(() => this.job()?.status === 'running' && !this.runningHere());
  readonly canResume = computed(() => {
    this.job();
    return this.imports.canResume(this.storageKey());
  });
  readonly progress = computed(() => {
    const job = this.job();
    return job?.total ? (100 * job.processed) / job.total : 0;
  });
  readonly failures = computed(() => this.job()?.outcomes.filter((o) => o.result === 'failed') ?? []);
  readonly successes = computed(() => this.job()?.outcomes.filter((o) => o.result !== 'failed') ?? []);

  readonly reading = signal(false);
  readonly downloading = signal(false);
  readonly readFailed = signal(false);
  readonly fileName = signal('');
  readonly sheets = signal<ImportSheet[]>([]);
  readonly sheetIndex = signal(0);
  readonly sheet = computed<ImportSheet | undefined>(() => this.sheets()[this.sheetIndex()]);

  private readonly acl = signal<Acl | undefined>(undefined);
  /** Textos traducidos por clave (etiquetas de los campos y de las opciones). */
  private readonly texts = signal<Record<string, string>>({});

  /** Campos que fija el contexto global y que se aplican a todas las filas. */
  readonly fixedColumns = computed(() => {
    const fixed = Object.keys(this.appState.fixedValues());
    return this.allColumns().filter((column) => fixed.includes(column.field));
  });
  /** Columnas que se pueden leer del Excel: las claves y las que el ACL deja escribir. */
  readonly columns = computed(() => {
    const blocked = this.blockedFields();
    const fixed = this.fixedColumns().map((column) => column.field);
    return this.allColumns().filter(
      (column) => !fixed.includes(column.field) && (column.key || !blocked.includes(column.field)),
    );
  });
  /** Columnas que el ACL no deja escribir. */
  readonly forbiddenLabels = computed(() => {
    const blocked = this.blockedFields();
    return this.allColumns()
      .filter((column) => !column.key && blocked.includes(column.field))
      .map((column) => column.text)
      .join(', ');
  });
  readonly canCreate = computed(() => this.allowed('create'));
  readonly canUpdate = computed(() => this.allowed('update'));
  readonly aclLoaded = computed(() => this.acl() !== undefined);

  /** Cabecera elegida para cada campo; se propone al cambiar de hoja y se puede corregir. */
  readonly mapping = linkedSignal<Record<string, number | null>>(() => {
    const sheet = this.sheet();
    if (!sheet) {
      return {};
    }
    const candidates = this.columns().map((column) => ({
      field: column.field,
      names: [column.text, column.field, ...(column.aliases ?? [])],
    }));
    return matchColumns(sheet.headers, candidates);
  });
  readonly missingKeys = computed(() => this.columns().filter((c) => c.key && this.mapping()[c.field] == null));
  /** Obligatorios para crear que no llegan del Excel: solo se podrán actualizar elementos existentes. */
  readonly missingRequired = computed(() =>
    this.columns().filter((c) => c.required && !c.key && this.mapping()[c.field] == null),
  );
  readonly unusedHeaders = computed(() => {
    const used = Object.values(this.mapping());
    return (this.sheet()?.headers ?? []).filter((header, index) => header && !used.includes(index));
  });
  readonly canStart = computed(
    () => !!this.sheet()?.rows.length && !this.missingKeys().length && (this.canCreate() || this.canUpdate()),
  );

  private readonly allColumns = computed<ExpectedColumn[]>(() => {
    const definition = this.definition();
    const texts = this.texts();
    return definition.columns
      .filter((column) => !SYSTEM_FIELDS.includes(column.field))
      .map((column) => ({
        ...column,
        text: texts[column.label] ?? column.field,
        key: definition.keys.includes(column.field),
      }));
  });

  private readonly blockedFields = computed(() => {
    const fields = this.acl()?.fields;
    return [...(fields?.noEditables ?? []), ...(fields?.noVisibles ?? [])];
  });

  constructor() {
    const destroyRef = inject(DestroyRef);
    const definition$ = toObservable(this.definition);
    definition$
      .pipe(
        switchMap((definition) => definition.target.acl().pipe(take(1))),
        takeUntilDestroyed(destroyRef),
      )
      .subscribe((acl) => this.acl.set(acl));
    definition$
      .pipe(
        switchMap((definition) => {
          const keys = definition.columns.flatMap((column) => [
            column.label,
            ...(column.options ?? []).map((option) => option.label),
          ]);
          if (!keys.length) {
            return of({});
          }
          return combineLatest(
            Object.fromEntries(keys.map((key) => [key, this.transloco.selectTranslate(key, {}, definition.scope)])),
          );
        }),
        takeUntilDestroyed(destroyRef),
      )
      .subscribe((texts) => this.texts.set(texts as Record<string, string>));

    // Una importación de otra pestaña que deja de latir pasa a interrumpida
    effect((onCleanup) => {
      if (this.runningElsewhere()) {
        const key = this.storageKey();
        const timer = setInterval(() => this.imports.refresh(key), REFRESH_MS);
        onCleanup(() => clearInterval(timer));
      }
    });
  }

  /** Primeros valores de la cabecera `index`; los de campos sensibles, enmascarados. */
  samples(field: string, index: number | null): string[] {
    if (index == null) {
      return [];
    }
    const values = (this.sheet()?.rows ?? [])
      .map((row) => row.cells[index])
      .filter((cell) => cell !== null && cell !== undefined && String(cell).trim() !== '')
      .slice(0, SAMPLES)
      .map((cell) => (cell instanceof Date ? cell.toLocaleString() : String(cell)));
    return this.definition().sensitive?.includes(field) ? values.map(() => '••••••') : values;
  }

  async read(event: Event): Promise<void> {
    const target = event.target as HTMLInputElement;
    const file = target.files?.[0];
    target.value = '';
    if (!file) {
      return;
    }
    this.reading.set(true);
    this.readFailed.set(false);
    try {
      const sheets = await readWorkbook(file);
      this.fileName.set(file.name);
      this.sheetIndex.set(
        Math.max(
          0,
          sheets.findIndex((sheet) => sheet.rows.length > 0),
        ),
      );
      this.sheets.set(sheets);
    } catch {
      this.readFailed.set(true);
    } finally {
      this.reading.set(false);
    }
  }

  /**
   * Descarga un Excel en blanco con las columnas que se pueden importar (las mismas etiquetas que reconoce el
   * emparejado) y una hoja de instrucciones con la clave, los obligatorios y el formato de cada columna.
   */
  async downloadTemplate(): Promise<void> {
    const t = (key: string, params?: Record<string, string>) =>
      this.transloco.translate(`common.import.${key}`, params);
    const columns = this.columns();
    this.downloading.set(true);
    try {
      await downloadTemplate(t('template.fileName', { entity: this.storageKey() }), {
        dataSheet: t('template.dataSheet'),
        headers: columns.map((column) => column.text),
        helpSheet: t('template.helpSheet'),
        help: [
          [t('template.column'), t('template.mandatory'), t('template.format')],
          ...columns.map((column) => [
            column.text,
            column.key ? t('mapping.key') : column.required ? t('mapping.required') : '',
            this.formatOf(column),
          ]),
        ],
      });
    } finally {
      this.downloading.set(false);
    }
  }

  /** Asigna la cabecera al campo; una cabecera solo puede ir a un campo. */
  assign(field: string, index: number | null): void {
    this.mapping.update((current) => {
      const next = { ...current };
      if (index != null) {
        Object.keys(next).forEach((other) => {
          if (next[other] === index) {
            next[other] = null;
          }
        });
      }
      next[field] = index;
      return next;
    });
  }

  back(): void {
    this.sheets.set([]);
    this.fileName.set('');
  }

  start(): void {
    const sheet = this.sheet();
    if (!sheet || !this.canStart()) {
      return;
    }
    const definition = this.definition();
    const mapping = this.mapping();
    const columns: ImportPlanColumn[] = this.columns()
      .filter((column) => mapping[column.field] != null)
      .map((column) => ({
        field: column.field,
        type: column.type ?? 'text',
        label: column.text,
        index: mapping[column.field]!,
        required: column.required,
        options: column.options?.map((option) => ({
          value: option.value,
          names: [option.value, this.texts()[option.label] ?? option.value],
        })),
      }));
    const plan: ImportPlan = {
      fileName: this.fileName(),
      columns,
      rows: sheet.rows,
      missingRequired: this.missingRequired().map((column) => column.text),
      sensitive: columns.some((column) => definition.sensitive?.includes(column.field)),
      canCreate: this.canCreate(),
      canUpdate: this.canUpdate(),
    };
    this.imports.start(definition, plan);
    this.back();
  }

  resume(): void {
    this.imports.resume(this.definition());
  }

  cancel(): void {
    this.imports.cancel(this.storageKey());
  }

  /** Descarta el resultado para empezar otra importación. */
  restart(): void {
    this.imports.clear(this.storageKey());
  }

  /** Formato o valores admitidos de una columna, para la hoja de instrucciones. */
  private formatOf(column: ExpectedColumn): string {
    if (column.type === 'enum' && column.options?.length) {
      return column.options.map((option) => this.texts()[option.label] ?? option.value).join(' / ');
    }
    return this.transloco.translate(`common.import.template.type.${column.type ?? 'text'}`);
  }

  private allowed(name: string): boolean {
    const acl = this.acl();
    return !!acl?.allAllowed || !!acl?.allows?.find((allow) => allow.name === name)?.allowed;
  }
}
